// What the exported page says, in the four languages the product speaks.
//
// Cut out of src/forensics/html-export.ts on 2026-09-16 (PLAN-2026-09-16 item 10.1), where it was
// 2,100 of that file's 6,664 lines. The builder imports it back and re-exports the name, so every
// existing import of html-export still works, and the page it builds is byte-identical.

import type { ResolvedUiLanguage } from '../i18n';
import { MARKER_STRINGS } from './marker-strings';
import { DASHBOARD_STRINGS } from './dashboard-strings';
import {
  PRETTY_TECHNIQUE_RO,
  PRETTY_TECHNIQUE_ES,
  PRETTY_TECHNIQUE_PT_BR,
} from './technique-labels';
import type { ExportLocale, ExportI18nStrings, DecisionFlatKeys } from '../types/export-strings';

/**
 * Per-locale display words laid over the English technique map. English is the
 * base, so a technique with no translation yet shows the English word rather
 * than a raw kebab id.
 */
export const TECHNIQUE_OVERLAY: Partial<Record<ExportLocale, Record<string, string>>> = {
  ro: PRETTY_TECHNIQUE_RO,
  es: PRETTY_TECHNIQUE_ES,
  'pt-BR': PRETTY_TECHNIQUE_PT_BR,
};


/**
 * The decision block's words, flattened into the export's string table so they
 * are digested with every other wording the export carries: one `why_<row>`
 * per policy row from the on-page table (the reader saw these very words) and
 * one `act_<action>` per action from the dashboard's table.
 */
function decisionFlat(lang: ResolvedUiLanguage): DecisionFlatKeys {
  const out: Record<string, string> = {};
  for (const [row, text] of Object.entries(MARKER_STRINGS[lang].whyByRow)) out[`why_${row}`] = text;
  // The family's own words, used on a band row (src/i18n/why-words.ts says which and why).
  for (const [family, text] of Object.entries(MARKER_STRINGS[lang].whyByFamily)) out[`whyfam_${family}`] = text;
  for (const [act, text] of Object.entries(DASHBOARD_STRINGS[lang].feedDecisionAction)) out[`act_${act}`] = text;
  return out as DecisionFlatKeys;
}

